const $=s=>document.querySelector(s), names=['January','February','March','April','May','June','July','August','September','October','November','December'];
const types={school:{label:'Schools',symbol:'▤',color:'#568568'},hospital:{label:'Hospitals & health',symbol:'+',color:'#498995'},kiln:{label:'Brick kilns',symbol:'▥',color:'#b77751'},government:{label:'Local government',symbol:'⌂',color:'#81759a'}};
let wind,boundary,pm,selected=0,groups={},counts={};
const map=L.map('map',{zoomControl:false,minZoom:11,maxZoom:18,attributionControl:true});L.control.zoom({position:'topright'}).addTo(map);
L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).addTo(map);
map.createPane('outside');map.getPane('outside').style.zIndex=410;map.getPane('outside').style.pointerEvents='none';
map.createPane('border');map.getPane('border').style.zIndex=420;map.getPane('border').style.pointerEvents='none';
for(const [key,t] of Object.entries(types)){groups[key]=L.layerGroup().addTo(map);counts[key]=0;const label=document.createElement('label');label.className='layer';label.style.setProperty('--color',t.color);label.innerHTML=`<span class="layer-icon">${t.symbol}</span><span class="layer-name">${t.label}</span><span class="count" id="count-${key}">…</span><input type="checkbox" role="switch" data-layer="${key}" aria-label="Show ${t.label.toLowerCase()}" checked>`;$('#layer-controls').append(label);label.querySelector('input').addEventListener('change',e=>{e.target.checked?groups[key].addTo(map):map.removeLayer(groups[key]);updateCount()})}
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function updateCount(){const visible=Object.keys(types).reduce((s,k)=>s+(map.hasLayer(groups[k])?counts[k]:0),0);$('#map-status').textContent=`${visible} mapped places visible`}
function color(v){const stops=[[0,[255,255,178]],[25,[254,204,92]],[50,[253,141,60]],[75,[240,59,32]],[100,[189,0,38]]];v=Math.max(0,Math.min(v,100));let i=Math.min(3,Math.floor(v/25)),t=(v-stops[i][0])/25;return `rgb(${stops[i][1].map((a,j)=>Math.round(a+(stops[i+1][1][j]-a)*t)).join(',')})`}
const Heat=L.Layer.extend({onAdd(m){this.m=m;this.canvas=L.DomUtil.create('canvas','pm-canvas');this.canvas.style.cssText='position:absolute;pointer-events:none;opacity:.78';m.getPanes().overlayPane.appendChild(this.canvas);m.on('moveend zoomend resize',this.draw,this);this.draw()},onRemove(m){m.off('moveend zoomend resize',this.draw,this);this.canvas.remove()},draw(){if(!this.m||!boundary)return;const m=this.m,size=m.getSize(),canvas=this.canvas,scale=devicePixelRatio||1;canvas.width=size.x*scale;canvas.height=size.y*scale;canvas.style.width=size.x+'px';canvas.style.height=size.y+'px';L.DomUtil.setPosition(canvas,m.containerPointToLayerPoint([0,0]));const ctx=canvas.getContext('2d');ctx.scale(scale,scale);ctx.beginPath();const polygons=boundary.features.flatMap(f=>f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates);for(const poly of polygons)for(const ring of poly){ring.forEach((p,i)=>{const q=m.latLngToContainerPoint([p[1],p[0]]);i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y)});ctx.closePath()}ctx.clip('evenodd');if(!pm)return;for(const c of pm.months[selected].cells){const a=m.latLngToContainerPoint([c.lat+.005,c.lon-.005]),b=m.latLngToContainerPoint([c.lat-.005,c.lon+.005]);ctx.fillStyle=color(c.pm25);ctx.fillRect(a.x,a.y,b.x-a.x+.5,b.y-a.y+.5)}}});const heat=new Heat();
function selectMonth(i){map.closePopup();selected=Number(i);renderWind();$('#month').value=selected;$('#map-month').value=selected;$('#month-name').textContent=names[selected];$('#selected-month').textContent=names[selected]+' 2024';$('#legend-month').textContent=names[selected]+' 2024 · satellite estimate';if(pm){$('#pm-value').textContent=pm.months[selected].mean.toFixed(1);document.querySelectorAll('.bar').forEach((b,k)=>{b.classList.toggle('active',k===selected);b.setAttribute('aria-pressed',k===selected)});if(map.hasLayer(heat))heat.draw()}}
$('#month').addEventListener('input',e=>selectMonth(e.target.value));$('#pm-toggle').addEventListener('change',e=>{if(e.target.checked)heat.addTo(map);else map.removeLayer(heat);$('.legend').style.display=e.target.checked?'block':'none'});$('#fit').onclick=()=>{if(boundary)map.fitBounds(L.geoJSON(boundary).getBounds(),{padding:[40,40]})};$('#reset-layers').onclick=()=>{document.querySelectorAll('[data-layer]').forEach(input=>{input.checked=true;groups[input.dataset.layer].addTo(map)});updateCount()};$('#source-open').onclick=()=>$('#sources').showModal();$('.close').onclick=()=>$('#sources').close();$('#sources').addEventListener('click',e=>{if(e.target===$('#sources')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)e.target.close()}});
async function loadMap(){try{boundary=await fetch('data/boundary.geojson').then(r=>{if(!r.ok)throw Error();return r.json()});const layer=L.geoJSON(boundary,{pane:'border',style:{color:'#54784e',weight:2,fill:false,dashArray:'5 4'}}).addTo(map);const bounds=layer.getBounds();map.fitBounds(bounds,{padding:[40,40]});map.setMaxBounds(bounds.pad(.22));const holes=boundary.features.flatMap(f=>f.geometry.type==='Polygon'?[f.geometry.coordinates[0]]:f.geometry.coordinates.map(p=>p[0]));L.geoJSON({type:'Feature',geometry:{type:'Polygon',coordinates:[[[-180,-85],[180,-85],[180,85],[-180,85],[-180,-85]],...holes]},properties:{}},{pane:'outside',interactive:false,style:{fillColor:'#f2f4ed',fillOpacity:1,stroke:false}}).addTo(map);if($('#pm-toggle').checked)heat.addTo(map);renderWind();const places=await fetch('data/places.geojson').then(r=>{if(!r.ok)throw Error();return r.json()});for(const f of places.features){const p=f.properties,key=p.category,t=types[key];if(!t)continue;const coords=f.geometry.coordinates;const marker=L.marker([coords[1],coords[0]],{icon:L.divIcon({className:'',html:`<div class="place-marker" style="--marker:${t.color}">${t.symbol}</div>`,iconSize:[25,25],iconAnchor:[12,12]}),title:p.name||t.label});let link=p.source_url||p.osm_url||'';marker.bindPopup(`<strong>${escapeHtml(p.name||'Unnamed '+t.label.toLowerCase())}</strong><div class="popup-type">${t.label} · Belauri</div>${p.facility_type?`<div class="popup-type">OSM: ${escapeHtml(p.facility_type)}</div>`:''}${link.startsWith('https://www.openstreetmap.org/')?`<a class="popup-link" href="${escapeHtml(link)}" target="_blank" rel="noopener">View mapped source ↗</a>`:''}`);groups[key].addLayer(marker);counts[key]++}Object.keys(types).forEach(k=>$('#count-'+k).textContent=counts[k]);updateCount()}catch(e){$('#map-status').textContent='Map data could not load. Please reload.';console.error(e)}}
async function loadPM(){try{pm=await fetch('data/pm25-2024.json').then(r=>{if(!r.ok)throw Error();return r.json()});if(pm.months.length!==12)throw Error('Expected 12 months');const max=Math.max(...pm.months.map(m=>m.mean));pm.months.forEach((m,i)=>{let b=document.createElement('button');b.className='bar';b.style.height=(m.mean/max*100)+'%';b.title=`${names[i]}: ${m.mean.toFixed(1)} µg/m³`;b.setAttribute('aria-label',b.title);b.onclick=()=>selectMonth(i);$('#chart').append(b)});$('#pm-note').textContent='V6GL03 · 0.01° grid. Area-weighted average within Belauri; map shows individual grid estimates.';$('#method').textContent=pm.methodology||pm.method;$('#download').disabled=false;$('#download').onclick=()=>{const rows=['month,year,pm25_ug_m3',...pm.months.map(m=>`${names[m.month-1]},2024,${m.mean.toFixed(3)}`)];const url=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='belauri-pm25-monthly-2024.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};selectMonth(selected)}catch(e){$('#pm-note').textContent='Satellite data could not load. Please reload; no estimated values have been substituted.';console.error(e)}}
loadMap();loadPM();fetch('data/provenance.json').then(r=>r.json()).then(p=>{$('#retrieved').textContent='Map snapshot retrieved '+(p.retrieved_date||p.retrieved_at||p.retrieved||p.retrieved_utc||'October 2026')+'.'}).catch(()=>{});

for(const [i,name] of names.entries()){const option=document.createElement('option');option.value=i;option.textContent=name+' 2024';$('#map-month').append(option)}
$('#map-month').addEventListener('change',e=>selectMonth(e.target.value));
$('#heat-opacity').addEventListener('input',e=>{const value=Number(e.target.value);$('#opacity-value').textContent=value+'%';if(heat.canvas)heat.canvas.style.opacity=value/100});
heat.on('add',()=>{heat.canvas.style.opacity=Number($('#heat-opacity').value)/100});
function inRing(point,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a[1]>point[1])!==(b[1]>point[1])&&point[0]<(b[0]-a[0])*(point[1]-a[1])/(b[1]-a[1])+a[0])inside=!inside}return inside}
map.on('click',e=>{if(!pm||!boundary||!map.hasLayer(heat))return;const p=[e.latlng.lng,e.latlng.lat];const polygons=boundary.features.flatMap(f=>f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates);if(!polygons.some(poly=>inRing(p,poly[0])&&!poly.slice(1).some(r=>inRing(p,r))))return;const cell=pm.months[selected].cells.find(c=>Math.abs(c.lat-p[1])<=.005&&Math.abs(c.lon-p[0])<=.005);if(!cell)return;L.popup().setLatLng(e.latlng).setContent(`<strong>${cell.pm25.toFixed(1)} µg/m³</strong><div class="popup-type">PM₂.₅ · ${names[selected]} 2024</div><div class="popup-type">Satellite grid estimate · 0.01°</div>`).openOn(map)});
$('#month').addEventListener('input',()=>map.closePopup());$('#map-month').addEventListener('change',()=>map.closePopup());


map.createPane('windGrid');map.getPane('windGrid').style.zIndex=415;map.getPane('windGrid').style.pointerEvents='none';
const WindGrid=L.Layer.extend({
 onAdd(m){this.m=m;this.canvas=L.DomUtil.create('canvas','wind-grid-canvas');this.canvas.style.cssText='position:absolute;pointer-events:none';m.getPane('windGrid').appendChild(this.canvas);m.on('moveend zoomend resize',this.draw,this);this.draw()},
 onRemove(m){m.off('moveend zoomend resize',this.draw,this);this.canvas.remove();this.m=null},
 draw(){if(!this.m)return;const m=this.m,size=m.getSize(),ratio=window.devicePixelRatio||1,c=this.canvas;c.width=size.x*ratio;c.height=size.y*ratio;c.style.width=size.x+'px';c.style.height=size.y+'px';L.DomUtil.setPosition(c,m.containerPointToLayerPoint([0,0]));const ctx=c.getContext('2d');ctx.scale(ratio,ratio);if(!boundary||!pm||!wind)return;const w=wind.months[selected];if(w.from_degrees===null||w.directional_consistency<.1)return;
 ctx.beginPath();const polygons=boundary.features.flatMap(f=>f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates);for(const poly of polygons)for(const ring of poly){ring.forEach((p,i)=>{const q=m.latLngToContainerPoint([p[1],p[0]]);i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y)});ctx.closePath()}ctx.clip('evenodd');
 for(const cell of pm.months[selected].cells){const q=m.latLngToContainerPoint([cell.lat,cell.lon]);if(q.x<-30||q.y<-30||q.x>size.x+30||q.y>size.y+30)continue;const next=m.latLngToContainerPoint([cell.lat,cell.lon+.01]);const length=Math.min(30,Math.max(6,Math.abs(next.x-q.x)*.62));ctx.save();ctx.translate(q.x,q.y);ctx.rotate(w.toward_degrees*Math.PI/180);ctx.beginPath();ctx.moveTo(0,length/2);ctx.lineTo(0,-length/2);ctx.moveTo(-length*.25,-length*.15);ctx.lineTo(0,-length/2);ctx.lineTo(length*.25,-length*.15);ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='rgba(255,255,255,.94)';ctx.lineWidth=4;ctx.stroke();ctx.strokeStyle='#173b58';ctx.lineWidth=1.8;ctx.stroke();ctx.restore()}
 }
});const windGrid=new WindGrid();

const compassNames=['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'];
function compassName(degrees){return compassNames[Math.round(degrees/22.5)%16]}
function renderWind(){if(!wind)return;const w=wind.months[selected],variable=w.from_degrees===null||w.directional_consistency<.1;const from=variable?'Variable direction':`From ${compassName(w.from_degrees)} · ${Math.round(w.from_degrees)%360}°`;const toward=variable?'No consistent monthly direction':`Blowing toward ${compassName(w.toward_degrees)}`;$('#wind-from').textContent=from;$('#wind-toward').textContent=toward;$('#wind-speed').textContent=`Mean speed ${w.mean_speed_ms.toFixed(1)} m/s`;$('#wind-arrow').style.transform=`rotate(${w.toward_degrees||0}deg)`;$('#wind-arrow').style.visibility=variable?'hidden':'visible';$('#wind-detail').textContent=`${names[selected]} 2024 · Same regional wind repeated across the PM₂.₅ grid. Arrows show travel direction.`;if($('#wind-toggle').checked){if(!map.hasLayer(windGrid))windGrid.addTo(map);else windGrid.draw()}else if(map.hasLayer(windGrid))map.removeLayer(windGrid)}
$('#wind-toggle').addEventListener('change',renderWind);
fetch('data/wind-2024.json').then(r=>{if(!r.ok)throw Error('Wind unavailable');return r.json()}).then(data=>{if(data.months.length!==12)throw Error('Incomplete wind data');wind=data;renderWind()}).catch(e=>{$('#wind-from').textContent='Wind data unavailable';$('#wind-detail').textContent='Please reload to try again.';console.error(e)});
